import * as React from "react";

/**
 * Double-tapping the nav item for the page you are already on takes you back to
 * the start of that page, in two steps: first the top of the scroll region,
 * then -- if the page has somewhere further back to go -- whatever it registered
 * as its start.
 *
 * The step is chosen from scroll position rather than from a second gesture
 * inside a time window, so the sequence is self-correcting: a double-tap when
 * scrolled always scrolls, and one at the top always resets.
 */

/** Milliseconds within which a second activation counts as a double. */
export const NAV_DOUBLE_MS = 350;

/** Scroll offsets below this count as "at the top" (sub-pixel, momentum drift). */
const AT_TOP_EPSILON = 4;

/**
 * A page publishes its start here; the nav consumes it. The two share no
 * parent -- the nav is Layout chrome and the tabs belong to the page -- so the
 * slot is a ref rather than state: it is read at click time and never needs to
 * re-render the nav.
 */
const NavResetContext = React.createContext<React.MutableRefObject<(() => void) | null> | null>(
  null,
);

export interface NavResetProviderProps {
  children: React.ReactNode;
}

/**
 * Installs the slot. `AppShell` renders this, so an app built on the shell has
 * it already. Without a provider `useRegisterNavReset` is inert and the nav
 * stops after the scroll step, which is what a page with no tabs wants anyway.
 */
export function NavResetProvider({ children }: NavResetProviderProps) {
  const slot = React.useRef<(() => void) | null>(null);
  return React.createElement(NavResetContext.Provider, { value: slot }, children);
}

/**
 * Registers what "back to the start" means for the page that calls it -- for a
 * tabbed page, selecting the first tab.
 *
 * ```tsx
 * useRegisterNavReset(() => setActiveTab(tabItems[0].id));
 * ```
 *
 * Pass `null` while the page has nowhere to go back to (already on the first
 * tab, or no tabs at all) and the nav's second step does nothing. The callback
 * is read through a ref, so an inline arrow does not re-register on every
 * render and the nav always invokes the latest one.
 */
export function useRegisterNavReset(fn: (() => void) | null): void {
  const slot = React.useContext(NavResetContext);
  const latest = React.useRef(fn);
  latest.current = fn;

  React.useEffect(() => {
    if (!slot) return;
    // `has` is what the nav tests to decide whether a second step exists, so it
    // has to track the CURRENT value rather than the one at registration time.
    const call = () => latest.current?.();
    const entry = latest.current ? call : null;
    slot.current = entry;
    return () => {
      if (slot.current === entry) slot.current = null;
    };
  });
}

/** The registered reset, or null. Consumed by the nav components. */
export function useNavReset(): React.MutableRefObject<(() => void) | null> | null {
  return React.useContext(NavResetContext);
}

/**
 * Resolves the scroll region the same way `useScrollReset` does: an element
 * with overflow of its own is the scroller, otherwise the window is. A Layout
 * hands its `AppMain` ref to both and each figures out the scroll model.
 */
function scroller(el: HTMLElement | null): { atTop: boolean; toTop: () => void } {
  if (el && el.scrollHeight > el.clientHeight) {
    return {
      atTop: el.scrollTop <= AT_TOP_EPSILON,
      toTop: () => el.scrollTo({ top: 0 }),
    };
  }
  return {
    atTop: window.scrollY <= AT_TOP_EPSILON,
    toTop: () => window.scrollTo(0, 0),
  };
}

/**
 * Returns the handler a nav item fires on activation. It only acts on the
 * SECOND activation within `NAV_DOUBLE_MS`, and only for the item whose page is
 * already showing -- activating any other item is a navigation, which owns the
 * gesture.
 */
export function useNavDoubleActivate(
  scrollRef?: React.RefObject<HTMLElement | null>,
): (active: boolean) => void {
  const resetSlot = useNavReset();
  const lastAt = React.useRef(0);

  return React.useCallback(
    (active: boolean) => {
      if (!active) {
        lastAt.current = 0;
        return;
      }
      const now = Date.now();
      if (now - lastAt.current > NAV_DOUBLE_MS) {
        lastAt.current = now;
        return;
      }
      // Consume the pair, so a third tap starts a new one rather than
      // triggering again off the second.
      lastAt.current = 0;

      const region = scroller(scrollRef?.current ?? null);
      if (!region.atTop) {
        region.toTop();
        return;
      }
      resetSlot?.current?.();
    },
    [resetSlot, scrollRef],
  );
}
